word = input().strip()

# Check if the word should be converted (Caps lock accidentally on)
# Case 1: All letters are uppercase
# Case 2: All letters except the first one are uppercase

if len(word) == 1:
    # Single character - if it's uppercase, convert to lowercase
    if word.isupper():
        print(word.lower())
    else:
        print(word)
else:
    # Check if all letters are uppercase
    if word.isupper():
        print(word.lower())
    # Check if all letters except the first are uppercase
    elif word[0].islower() and word[1:].isupper():
        result = word[0].upper() + word[1:].lower()
        print(result)
    else:
        print(word)
```

